def compute(vars):
    net_losses = [vars["v1"], vars["v2"]]
    average_net_loss = sum(net_losses) / len(net_losses)
    return {
        "value": average_net_loss,
        "trace": {
            "net_losses": net_losses,
            "count": len(net_losses),
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
